export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const db = getDb();
  const row = db
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  const sequence = db
    .select({ value: issueNumberSequences.lastNumber })
    .from(issueNumberSequences)
    .where(
      and(
        eq(issueNumberSequences.orgId, orgId),
        eq(issueNumberSequences.projectId, projectId),
      ),
    )
    .get();
  return Math.max(row?.value ?? 0, sequence?.value ?? 0) + 1;
}

