/**
 * Moves one issue and allocates its target number in the same transaction.
 * Both project counters are retained, so leaving a project never frees a
 * number for later reuse.
 */
export async function moveIssueToProject(
  orgId: OrgId,
  issueId: IssueId,
  toProjectId: ProjectId,
): Promise<Issue> {
  const db = getDb();
  const row = db.transaction((tx) => {
    const before = tx
      .select()
      .from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .get();

    if (!before) throw new Error(`Issue ${issueId} not found`);
    if (before.projectId === toProjectId) return before;

    const targetMax = tx
      .select({ value: sql<number | null>`max(${issues.number})` })
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, toProjectId),
        ),
      )
      .get();
    const targetSequence = tx
      .select({ value: issueNumberSequences.lastNumber })
      .from(issueNumberSequences)
      .where(
        and(
          eq(issueNumberSequences.orgId, orgId),
          eq(issueNumberSequences.projectId, toProjectId),
        ),
      )
      .get();
    const toNumber = Math.max(
      targetMax?.value ?? 0,
      targetSequence?.value ?? 0,
    ) + 1;

    const rememberNumber = (projectId: string, number: number) =>
      tx
        .insert(issueNumberSequences)
        .values({ orgId, projectId, lastNumber: number })
        .onConflictDoUpdate({
          target: [issueNumberSequences.orgId, issueNumberSequences.projectId],
          set: {
            lastNumber: sql`max(${issueNumberSequences.lastNumber}, ${number})`,
          },
        })
        .run();

    rememberNumber(before.projectId, before.number);
    rememberNumber(toProjectId, toNumber);

    const moved = tx
      .update(issues)
      .set({
        projectId: toProjectId,
        number: toNumber,
        updatedAt: toIsoTimestamp(new Date()),
      })
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .returning()
      .get();

    if (!moved) throw new Error(`Issue ${issueId} not found`);
    return moved;
  });

